export async function detectRuntime(){try{const r=await fetch('/api/config',{signal:AbortSignal.timeout(2000)});if(!r.ok)return {mode:'browser'};const data=await r.json();return data.mode==='docker'?data:{mode:'browser'}}catch{return {mode:'browser'}}}
export async function api(path,{method='GET',data,signal}={}){const r=await fetch(path,{method,headers:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined,signal});let body;try{body=await r.json()}catch{throw Error('Răspuns invalid de la serviciu.')}if(!r.ok)throw Error(body.error||'Serviciu indisponibil');return body}
export function startSimulation(model,runtime,onResult,onError){if(runtime.mode==='docker'){const abort=new AbortController();api('/api/simulations',{method:'POST',data:{model},signal:abort.signal}).then(data=>onResult(data.result)).catch(e=>{if(e.name!=='AbortError')onError(e.message)});return {terminate:()=>abort.abort()}}
 const worker=new Worker(new URL('../network-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{worker.terminate();data.error?onError(data.error):onResult(data.result)};worker.onerror=()=>{worker.terminate();onError('Eroare în simulare.')};worker.postMessage({model});return worker;
}
